source("helper.R")
d2 <- bytes(c("1", "-2"), 16)
cat("F1 vendor not checked:\n"); print(zuarrow::arrow_to_r(mk(opaque(json = '{"type_name":"hugeint","vendor_name":"Other"}'), d2, 2)))
cat("F1b nested object:\n"); print(zuarrow::arrow_to_r(mk(opaque(json = '{"extra":{"type_name":"hugeint"},"type_name":"uuid","vendor_name":"DuckDB"}'), d2, 2)))
cat("F2 valid JSON not recognised:\n"); print(class(zuarrow::arrow_to_r(mk(opaque(json = '{"vendor_name":"DuckDB","note":"type_name","type_name":"hugeint"}'), d2, 2))))
print(class(zuarrow::arrow_to_r(mk(opaque(json = '{"type_name":"huge\\u0069nt","vendor_name":"DuckDB"}'), d2, 2))))
cat("F3 INT32_MIN to int64:\n"); print(tryCatch(zuarrow::arrow_to_r(mk(na_int32(), bytes(c("-2147483648", "5"), 4), 2), to = int64()), error = function(e) conditionMessage(e)))
print(zuarrow::arrow_to_r(mk(na_int32(), bytes(c("-2147483648", "5"), 4), 2), to = int64(), lossy = "allow"))
print(zuarrow::arrow_to_r(mk(na_int32(), bytes(c("-2147483648", "5"), 4), 2), to = int64(), lossy = "character"))
cat("F4 to = uint128() ignored:\n"); print(zuarrow::arrow_to_r(mk(na_decimal128(38, 0), bytes("340282366920938463463374607431768211454", 16), 1), to = uint128()))
print(zuarrow::arrow_to_r(mk(opaque("hugeint"), d2, 2), to = uint128())); print(class(zuarrow::arrow_to_r(mk(na_int64(), bytes("5", 8), 1), to = int128())))
cat("F5 decimal storage under arrow.opaque, no `to`:\n"); print(zuarrow::arrow_to_r(mk(opaque("uuid", storage = na_decimal128(38, 0)), d2, 2)))
print(tryCatch(zuarrow::arrow_to_r(mk(na_decimal128(38, 0), d2, 2)), error = function(e) class(e)[1]))
cat("F6 lossy = 'error' yet values lost with a warning:\n"); print(zuarrow::arrow_to_r(mk(na_int64(), bytes(c("-1", "5"), 8), 2), to = uint64(), lossy = "error"))
